TEST(dxbc_checksum_of_compiled_shaders) {
    // fxc's own checksum is reproduced, and a changed byte is noticed.
    CHECK(dxbcChecksumValid(kHost) && dxbcChecksumValid(kFilter) && dxbcChecksumValid(kBadFilter));
    std::vector<uint8_t> broken = kHost;
    broken[broken.size() - 5] ^= 1;
    CHECK(!dxbcChecksumValid(broken));
    CHECK(!dxbcChecksumValid(std::vector<uint8_t>(40, 0)));
    DxbcInfo info;
    std::string err;
    CHECK(dxbcInspect(kHost, info, &err));
    CHECK(info.pixelShader && info.major == 5 && info.minor == 0 && info.outputWrites >= 1 && info.rets == 1 && info.endsInRet && info.temps >= 1);
    CHECK(!dxbcInspect(std::vector<uint8_t>(64, 0), info, &err) && !err.empty());
}

TEST(dxbc_splice_filter_into_shader) {
    DxbcInfo host, filter, spliced;
    CHECK(dxbcInspect(kHost, host) && dxbcInspect(kFilter, filter));
    std::vector<uint8_t> out;
    std::string err;
    CHECK(dxbcSpliceFilter(kHost, kFilter, out, &err));
    CHECK(err.empty());
    CHECK(dxbcChecksumValid(out));
    CHECK(dxbcInspect(out, spliced, &err));
    // The host's instructions, then the filter's without its return; one more temp for the host's colour, then the
    // filter's own; the output is written by the filter now, not by the host.
    CHECK(spliced.instructions == host.instructions + filter.instructions - 1);
    CHECK(spliced.temps == host.temps + 1 + filter.temps);
    CHECK(spliced.rets == 1 && spliced.endsInRet);
    CHECK(spliced.outputWrites == filter.outputWrites);
    CHECK(out.size() > kHost.size() && out.size() < kHost.size() + kFilter.size());
    CHECK(std::memcmp(&out[28], &kHost[28], 4) == 0);  // the same chunks
    // Spliced twice, the filter runs twice.
    std::vector<uint8_t> twice;
    CHECK(dxbcSpliceFilter(out, kFilter, twice, &err));
    DxbcInfo t;
    CHECK(dxbcInspect(twice, t) && t.instructions == spliced.instructions + filter.instructions - 1 && dxbcChecksumValid(twice));
    // Refused: a filter with a texture, and blobs that are no shaders.
    CHECK(!dxbcSpliceFilter(kHost, kBadFilter, out, &err) && out.empty() && err.find("filter shader") != std::string::npos);
    CHECK(!dxbcSpliceFilter(std::vector<uint8_t>(100, 0), kFilter, out, &err) && err.find("stock shader") != std::string::npos);
    CHECK(!dxbcSpliceFilter(kHost, std::vector<uint8_t>(100, 0), out, &err));
}

TEST(dxbc_splice_screen_filter) {
    DxbcInfo host, filter, spliced;
    CHECK(dxbcInspect(kScreenHost, host) && dxbcInspect(kScreenFilter, filter) && dxbcChecksumValid(kScreenHost) && dxbcChecksumValid(kScreenFilter));
    std::vector<uint8_t> out, added;
    std::string err;
    // The host declares t3 as a 2D texture: the filter's t0 becomes t3, its input 1 the host's position input.
    DxbcSpliceOptions at3;
    at3.sceneDepthRegister = 3;
    CHECK(dxbcSpliceFilter(kScreenHost, kScreenFilter, out, &err, at3));
    CHECK(err.empty() && dxbcChecksumValid(out));
    CHECK(dxbcInspect(out, spliced, &err));
    CHECK(spliced.instructions == host.instructions + filter.instructions - 1);
    CHECK(spliced.temps == host.temps + 1 + filter.temps && spliced.rets == 1 && spliced.endsInRet);
    // A register the host does not declare: the filter's declaration is added (one more declaration, the same code).
    DxbcSpliceOptions at9;
    at9.sceneDepthRegister = 9;
    CHECK(dxbcSpliceFilter(kScreenHost, kScreenFilter, added, &err, at9));
    DxbcInfo withDecl;
    CHECK(dxbcChecksumValid(added) && dxbcInspect(added, withDecl) && withDecl.instructions == spliced.instructions);
    CHECK(added.size() > out.size());
    // t0 of the host is a 2D texture too, so it can serve; the result differs from the t3 one only in the register.
    DxbcSpliceOptions at0;
    at0.sceneDepthRegister = 0;
    std::vector<uint8_t> zero;
    CHECK(dxbcSpliceFilter(kScreenHost, kScreenFilter, zero, &err, at0) && zero.size() == out.size() && zero != out);
    // Refused: a host without a screen position; a screen filter spliced as a plain one (it declares a texture and a
    // second input); a plain filter is still spliced in screen mode (it reads neither).
    CHECK(!dxbcSpliceFilter(kPlainHost, kScreenFilter, out, &err, at3) && out.empty() && err.find("screen position") != std::string::npos);
    CHECK(!dxbcSpliceFilter(kScreenHost, kScreenFilter, out, &err) && err.find("filter shader") != std::string::npos);
    CHECK(dxbcSpliceFilter(kScreenHost, kFilter, out, &err, at3) && dxbcChecksumValid(out));
}
